def bands(g,H,W):
    sep={c for c in range(W) if len({g[r][c] for r in range(H)})==1}
    bs=[];start=None
    for c in range(W):
        if c in sep:
            if start is not None: bs.append((start,c-1)); start=None
        else:
            if start is None: start=c
    if start is not None: bs.append((start,W-1))
    return bs,bstart=start
# group colors per band; assume each band has one dominant nonzero color
def solve(g,verbose=False):
    H=len(g); W=len(g[0]); bands_,_=bands(g,H,W)
    bands_=[b for b in bands_ if len(b)>1]  # skip separator-only groups
    doms={}
    for s,e in bands_:
        cnt=collections.Counter(g[r][c] for r in range(H) for c in range(s,e+1) if g[r][c]!=0)
        v,nz=cnt.most_common(1)[0]
        doms[v]=[(r-(s if False else None),c-s) for r in range(H) for c in range(s,e+1) if g[r][c]==v]
    res=[]
    for r in range(H):
        row=[]
        for c in range(H):
            sc={}
            for v,m in doms.items():
                sc[v]=sum(1 for a,bb in m if a>=r and bb>=c)
            best=max(sc.values())
            cand=[v for v,k in sc.items() if k==best]
            row.append(max(cand))
        res.append(row)
    return res
